        int next_fd;
        char *head;

        /* Only relative paths without consecutive slashes */
        assert(path[0] != '/');

        head = g_strdup(path);
        c = strchr(path, '/');
        if (c) {
            head[c - path] = 0;
            next_fd = openat_dir(fd, head);
        } else {
            next_fd = openat_file(fd, head, flags, mode);
