typedef struct FsContext
{
    uid_t uid;
    char *fs_root;
    int export_flags;
    struct xattr_operations **xops;
    struct extended_ops exops;
    FsThrottle *fst;
    /* fs driver specific data */
    void *private;
} FsContext;

